arguments.command:
cd /logs/agent && python3 << 'EOF'
import json

with open('output.json', 'r') as f:
    data = json.load(f)

# Verify code_application_table and response_count_per_code consistency
print("Checking code_application_table consistency:")
for code, responses in data['code_application_table'].items():
    expected_count = data['response_count_per_code'][code]
    actual_count = len(responses)
    if expected_count != actual_count:
        print(f"  MISMATCH: {code} - count says {expected_count}, table has {actual_count}")
    else:
        print(f"  OK: {code} = {actual_count}")

# Verify per-response assessments
print("\nPer-response checks:")
for resp in data['per_response_assessment']:
    rid = resp['response_id']
    reasons = resp['failure_reasons']
    primary = resp['primary_failure_code']
    evidence_keys = set(resp['failure_reason_evidence'].keys())
    reason_set = set(reasons)

    # Check primary in reasons or NONE case
    if primary == "NONE":
        if reasons != []:
            print(f"  {rid}: ERROR - primary is NONE but failure_reasons not empty")
    else:
        if primary not in reason_set:
            print(f"  {rid}: ERROR - primary '{primary}' not in failure_reasons")

    # Check code_application_count
    if resp['code_application_count'] != len(reasons):
        print(f"  {rid}: ERROR - code_application_count {resp['code_application_count']} != len(reasons) {len(reasons)}")

    # Check primary_in_set_check
    if resp['primary_failure_code'] == "NONE":
        expected = (len(reasons) == 0)
    else:
        expected = (resp['primary_failure_code'] in reasons)
    if resp['primary_in_set_check'] != expected:
        print(f"  {rid}: ERROR - primary_in_set_check {resp['primary_in_set_check']} but expected {expected}")

    # Check evidence_key_completeness
    if evidence_keys != reason_set:
        print(f"  {rid}: ERROR - evidence keys {evidence_keys} != failure_reasons {reason_set}")
    if resp['evidence_key_completeness'] != len(reason_set):
        print(f"  {rid}: ERROR - evidence_key_completeness {resp['evidence_key_completeness']} != len(reasons) {len(reason_set)}")

    # Check evidence quotes length
    for code, quote in resp['failure_reason_evidence'].items():
        if len(quote) < 20:
            print(f"  {rid}: ERROR - evidence for {code} is only {len(quote)} chars (<20)")

    # Check primary evidence length
    if len(resp['primary_failure_code_evidence']) < 50:
        print(f"  {rid}: ERROR - primary evidence is only {len(resp['primary_failure_code_evidence'])} chars (<50)")

    # Check alternative codes
    if len(resp['alternative_codes_considered']) < 2:
        print(f"  {rid}: ERROR - only {len(resp['alternative_codes_considered'])} alternatives (<2)")
    for alt in resp['alternative_codes_considered']:
        if len(alt['reason_excluded']) < 20:
            print(f"  {rid}: ERROR - reason_excluded for {alt['code']} is only {len(alt['reason_excluded'])} chars (<20)")

    # Check cross-response observations length
    if len(data['cross_response_observations']) < 300:
        print(f"  ERROR: cross_response_observations is only {len(data['cross_response_observations'])} chars (<300)")

    print(f"  {rid}: All checks passed")

print("\n=== All verifications complete ===")
EOF
